            pSpawn->posY = -rand() % g_BattleSpecialHiddenOneCardSpreadRadius;
            pSpawn->posZ = g_BattleSpecialHiddenOneCardPosition[2] + rand() % (g_BattleSpecialHiddenOneCardSpreadRadius << 1) - g_BattleSpecialHiddenOneCardSpreadRadius;
